import type { SessionMeasureInput } from 'claude-code'

import type { LogEntry, Reading, Turn } from '../types'
import type { Lang, Strings, Units } from './i18n'
import { STRINGS } from './i18n'

// Pure data logic: no $, so it is tested on its own.

export const FIVE_HOURS = 5 * 60 * 60 * 1000

export type Heat = 'calm' | 'warn' | 'hot'

export type Measure = Pick<SessionMeasureInput, 'context' | 'rateLimits' | 'cost'>

export const heat = (percent: number): Heat => (percent >= 75 ? 'hot' : percent >= 50 ? 'warn' : 'calm')

export const takeReading = (m: Measure): Reading => {
  const limit = (kind: string) => m.rateLimits.find(l => l.kind === kind)
  const resetsAt = (kind: string) => {
    const at = Date.parse(limit(kind)?.resetsAt ?? '')
    return Number.isFinite(at) ? at : undefined
  }
  return {
    fiveHour: limit('five_hour')?.percentUsed,
    fiveHourResetsAt: resetsAt('five_hour'),
    sevenDay: limit('seven_day')?.percentUsed,
    sevenDayResetsAt: resetsAt('seven_day'),
    ctxPercent: m.context.percent,
    ctxTokens: m.context.tokens,
    ctxWindow: m.context.window,
    usd: m.cost?.usd,
  }
}

export const tokens = (n: number): string => {
  if (n >= 1_000_000) return `${Number((n / 1_000_000).toFixed(1))}M`
  return n >= 1000 ? `${Math.round(n / 1000)}k` : `${n}`
}

export const percentText = (percent: number | undefined): string =>
  percent === undefined ? '-' : `${Math.round(percent)}%`

// Under a day: hours and minutes; over a day: days and hours (minutes are noise for the 7-day window).
// step: minutes are rounded up to it (5 keeps a long countdown from changing, and redrawing, every minute).
export const countdown = (ms: number, u: Units = STRINGS.tr.units, step = 1): string => {
  const part = (n: number, unit: string) => `${n}${u.numSep}${unit}`
  const m = Math.max(0, Math.ceil(ms / 60000 / step) * step)
  if (m < 60) return part(m, u.m)
  if (m >= 24 * 60) {
    const days = Math.floor(m / (24 * 60))
    const hours = Math.floor((m % (24 * 60)) / 60)
    return hours === 0 ? part(days, u.d) : `${part(days, u.d)}${u.partSep}${part(hours, u.h)}`
  }
  const h = Math.floor(m / 60)
  const rest = m % 60
  return rest === 0 ? part(h, u.h) : `${part(h, u.h)}${u.partSep}${part(rest, u.m)}`
}

// The time in the system locale's own format: 16:20 in Turkey, 4:20 PM in the US.
// 24-hour locales keep the leading zero (09:05).
export const clockTime = (ms: number, locale?: string): string => {
  const cycle = new Intl.DateTimeFormat(locale, { hour: 'numeric' }).resolvedOptions().hourCycle
  const hour = cycle === 'h23' || cycle === 'h24' ? '2-digit' : 'numeric'
  return new Intl.DateTimeFormat(locale, { hour, minute: '2-digit' }).format(new Date(ms))
}

// The weekday comes from Intl in that language (Pzt, Mon, lun., 月 ...).
export const dayClock = (ms: number, lang: Lang = 'tr'): string =>
  `${new Intl.DateTimeFormat(lang, { weekday: 'short' }).format(new Date(ms))} ${clockTime(ms)}`

export const windowElapsed = (resetsAt: number, now: number, length = FIVE_HOURS): number =>
  Math.min(1, Math.max(0, 1 - (resetsAt - now) / length))

// What a narrow band drops: the cost first (under 70 columns), then the ctx token count (under 55).
// The rings and the percentages are never dropped.
export const bandLayout = (columns: number): { showJet: boolean; showCost: boolean; showCtxTokens: boolean } => ({
  showJet: columns >= 85,
  showCost: columns >= 70,
  showCtxTokens: columns >= 55,
})

export const HISTORY_LIMIT = 6
export const NUDGE_AT = 55
export const SETTLE_MS = 2000

export type TurnUsage = {
  input_tokens: number
  output_tokens: number
  cache_read_input_tokens: number
  cache_creation_input_tokens: number
  model?: string
}

// turn.complete's usage sums every response of the turn, so the context fill cannot come from it.
// A turn is recorded with the latest reading's ctx and total cost; settleTurn corrects it with a later measurement.
export const recordTurn = (
  history: readonly Turn[],
  usage: TurnUsage,
  ctxPercent: number,
  usd: number | undefined,
  at: number,
  fiveHour?: number,
): Turn[] => {
  const turn: Turn = {
    n: (history.at(-1)?.n ?? 0) + 1,
    at,
    ctxPercent,
    ...(usd !== undefined && { usd }),
    ...(fiveHour !== undefined && { fiveHour }),
    ...(usage.model !== undefined && { model: usage.model }),
    in: usage.input_tokens,
    out: usage.output_tokens,
    cacheRead: usage.cache_read_input_tokens,
    cacheWrite: usage.cache_creation_input_tokens,
  }
  return [...history, turn].slice(-HISTORY_LIMIT)
}

// turn.complete and session.measure arrive in no promised order. A measurement within SETTLE_MS of the turn's end
// belongs to that turn and corrects the fields it carries; a later one is the middle of the next turn.
export const settleTurn = (
  history: readonly Turn[],
  patch: { ctxPercent?: number; usd?: number; fiveHour?: number },
  now: number,
): Turn[] => {
  const last = history.at(-1)
  if (!last || now - last.at > SETTLE_MS) return [...history]
  return [
    ...history.slice(0, -1),
    {
      ...last,
      ...(patch.ctxPercent !== undefined && { ctxPercent: patch.ctxPercent }),
      ...(patch.usd !== undefined && { usd: patch.usd }),
      ...(patch.fiveHour !== undefined && { fiveHour: patch.fiveHour }),
    },
  ]
}

// $.state history from v0.4 and earlier carries a single cache field: it counts as reads, writes 0.
export type LegacyTurn = Omit<Turn, 'cacheRead' | 'cacheWrite'> & { cache?: number; cacheRead?: number; cacheWrite?: number }

export const upgradeTurn = (t: LegacyTurn): Turn => {
  const { cache, ...rest } = t
  return { ...rest, cacheRead: t.cacheRead ?? cache ?? 0, cacheWrite: t.cacheWrite ?? 0 }
}

// Pass the returned nudgedAt to the next call. When the fill drops below nudgedAt (clear, compact) the nudge re-arms.
export const nudge = (ctxPercent: number, nudgedAt: number): { nudgedAt: number; shouldToast: boolean } => {
  const armed = ctxPercent < nudgedAt ? 0 : nudgedAt
  if (ctxPercent >= NUDGE_AT && ctxPercent >= armed + 10) {
    return { nudgedAt: Math.floor(ctxPercent / 10) * 10, shouldToast: true }
  }
  return { nudgedAt: armed, shouldToast: false }
}

export const nudgeText = (ctxPercent: number, t: Pick<Strings, 'nudge'> = STRINGS.tr): string =>
  t.nudge(Math.round(ctxPercent))

export const RECENT = 5

export const turnTotal = (t: Turn): number => t.in + t.out + t.cacheRead + t.cacheWrite

// The last RECENT turns, newest first. delta: the turn's ctx minus the previous turn's; cost: the session's total
// cost at the turn's end minus the previous one's (the engine's own ledger); five: how far the 5-hour window moved
// over the turn (negative when it reset in between). All null without a previous turn, except the session's first
// turn's cost, which counts from baseUsd (the session's cost when it started).
export type RecentTurn = { turn: Turn; delta: number | null; cost: number | null; five: number | null }

// The session's total before the turn is the previous turn's, or for the first turn the cost at session start.
const turnCost = (turn: Turn, prev: Turn | undefined, baseUsd: number | undefined): number | null => {
  const before = prev ? prev.usd : turn.n === 1 ? baseUsd : undefined
  return before !== undefined && turn.usd !== undefined ? turn.usd - before : null
}

export const recentTurns = (history: readonly Turn[], baseUsd?: number): RecentTurn[] =>
  history
    .map((turn, i) => {
      const prev = i > 0 ? history[i - 1] : undefined
      return {
        turn,
        delta: prev ? turn.ctxPercent - prev.ctxPercent : null,
        cost: turnCost(turn, prev, baseUsd),
        five: prev?.fiveHour !== undefined && turn.fiveHour !== undefined ? turn.fiveHour - prev.fiveHour : null,
      }
    })
    .slice(-RECENT)
    .reverse()

export const ctxDeltaText = (delta: number | null, ctxPercent: number): string => {
  if (delta === null) return `${Math.round(ctxPercent)}%`
  const d = Math.round(delta)
  return d > 0 ? `+${d}%` : d < 0 ? `${d}%` : '±0%'
}

// The 5-hour window's move over one turn: +0.4%, +1%, ±0%, the reset word when it went down, '' when unknown.
export const fiveDeltaText = (five: number | null, resetWord: string): string => {
  if (five === null) return ''
  if (five < 0) return resetWord
  const n = Number(five.toFixed(1))
  return n === 0 ? '±0%' : `+${n}%`
}

// The section's summary line: tokens, cost and the 5-hour window's growth over the shown turns (resets skipped).
export const turnsSummary = (rows: readonly RecentTurn[]): { tokens: number; cost: number | null; five: number | null } => {
  const costs = rows.map(r => r.cost).filter((c): c is number => c !== null)
  const fives = rows.map(r => r.five).filter((f): f is number => f !== null && f >= 0)
  return {
    tokens: rows.reduce((a, r) => a + turnTotal(r.turn), 0),
    cost: costs.length ? costs.reduce((a, c) => a + c, 0) : null,
    five: fives.length ? fives.reduce((a, f) => a + f, 0) : null,
  }
}

export const costText = (cost: number | null): string => {
  if (cost === null) return ''
  return cost < 0.01 ? '<$0.01' : `$${cost.toFixed(2)}`
}

// The cache ring drains every minute; drawn in 5% steps its Svg changes (and reloads) every few minutes instead.
export const ringStep = (percent: number): number => Math.round(percent / 5) * 5

export const TTL_1H = 60 * 60 * 1000
export const TTL_5M = 5 * 60 * 1000
export const SEVEN_DAYS = 7 * 24 * 60 * 60 * 1000
export const LOG_KEEP_MS = 8 * 24 * 60 * 60 * 1000
export const LOG_LIMIT = 2000

export type CacheState = { percent: number; text: string; isWarm: boolean }

// The countdown starts at the turn's end, a little after its last request began, so it is an upper bound.
export const COUNTDOWN_STEP = 5

export const cacheState = (
  lastRequestAt: number | null,
  ttlMs: number,
  now: number,
  t: Pick<Strings, 'units' | 'cold'> = STRINGS.tr,
): CacheState | null => {
  if (lastRequestAt === null) return null
  const left = lastRequestAt + ttlMs - now
  if (left <= 0) return { percent: 0, text: t.cold, isWarm: false }
  // A long lifetime counts down in 5-minute steps, matching the ring's 5% steps; the 5-minute one by the minute.
  const step = ttlMs >= 30 * 60 * 1000 ? COUNTDOWN_STEP : 1
  const text = left < 60_000 ? `<1${t.units.numSep}${t.units.m}` : countdown(left, t.units, step)
  // The ring drains with the shown countdown, so both change on the same minute.
  const stepMs = step * 60_000
  return { percent: Math.min(100, (Math.ceil(left / stepMs) * stepMs * 100) / ttlMs), text, isWarm: true }
}

export const parseTtl = (arg: string): number | undefined => (arg === '5m' ? TTL_5M : arg === '1h' ? TTL_1H : undefined)

export const ttlText = (ms: number, t: Pick<Strings, 'ttl5m' | 'ttl1h'> = STRINGS.tr): string =>
  ms === TTL_5M ? t.ttl5m : t.ttl1h

// An unknown project or model is stored as the language-neutral ?; shown as t.unknown. v0.7 logs wrote bilinmiyor.
export const UNKNOWN = '?'
const LEGACY_UNKNOWN = 'bilinmiyor'
export const isUnknown = (name: string): boolean => name === UNKNOWN || name === LEGACY_UNKNOWN

export const projectName = (cwd: string): string => cwd.split(/[\\/]/).filter(Boolean).at(-1) ?? UNKNOWN

export const modelName = (id: string | undefined): string =>
  id === undefined ? UNKNOWN : id.replace(/^claude-/, '').replace(/\[1m\]$/, '')

// Adds this session's last turn to the log, or updates it under the same id after a settle. When the turn has no
// model (an interrupted turn, the turn of a hot reload) the session's model is used; earlier unknown rows are fixed too.
export const syncLog = (
  log: readonly LogEntry[],
  turn: Turn,
  prev: Turn | undefined,
  project: string,
  sessionModel?: string,
  baseUsd?: number,
): LogEntry[] => {
  const fallback = sessionModel === undefined ? UNKNOWN : modelName(sessionModel)
  const usd = turnCost(turn, prev, baseUsd)
  const entry: LogEntry = {
    id: String(turn.at),
    at: turn.at,
    project,
    model: turn.model === undefined ? fallback : modelName(turn.model),
    tokens: turnTotal(turn),
    ...(usd !== null && { usd }),
  }
  const repaired = log.map(e => (isUnknown(e.model) ? { ...e, model: fallback } : e))
  // The same turn may sit under its older id (the turn number before v1.2.5): its time matches.
  return [...repaired.filter(e => e.id !== entry.id && e.at !== entry.at), entry].slice(-LOG_LIMIT)
}

export type WindowView = '5h' | '7d'

export const windowStart = (view: WindowView, r: Reading | null, now: number): number =>
  view === '5h' ? (r?.fiveHourResetsAt ?? now) - FIVE_HOURS : (r?.sevenDayResetsAt ?? now) - SEVEN_DAYS

export type Group = { name: string; tokens: number; turns: number; usd: number }

export const breakdown = (entries: readonly LogEntry[], since: number, by: 'project' | 'model', limit = 5): Group[] => {
  const groups = new Map<string, Group>()
  for (const e of entries) {
    if (e.at < since) continue
    const name = isUnknown(e[by]) ? UNKNOWN : e[by]
    const g = groups.get(name) ?? { name, tokens: 0, turns: 0, usd: 0 }
    groups.set(name, { name, tokens: g.tokens + e.tokens, turns: g.turns + 1, usd: g.usd + (e.usd ?? 0) })
  }
  return [...groups.values()].sort((a, b) => b.usd - a.usd || b.tokens - a.tokens).slice(0, limit)
}

export const windowTotals = (entries: readonly LogEntry[], since: number): { turns: number; tokens: number; usd: number } =>
  entries
    .filter(e => e.at >= since)
    .reduce((t, e) => ({ turns: t.turns + 1, tokens: t.tokens + e.tokens, usd: t.usd + (e.usd ?? 0) }), { turns: 0, tokens: 0, usd: 0 })

// Another session's log is deleted when it is empty, malformed, or its last turn is older than LOG_KEEP_MS.
export const isStaleLog = (entries: unknown, now: number): boolean => {
  if (!Array.isArray(entries) || entries.length === 0) return true
  const last: unknown = entries.at(-1)
  const at = typeof last === 'object' && last !== null ? Reflect.get(last, 'at') : undefined
  return typeof at !== 'number' || at < now - LOG_KEEP_MS
}

// The 5-hour window's percent at a moment, kept for the run-out forecast's recent pace.
export type Sample = { at: number; pct: number }
export const RECENT_MS = 30 * 60 * 1000
const MIN_SPAN_MS = 5 * 60 * 1000

// Adds a reading when the percent moved; a drop (a new window) starts over, and samples past twice RECENT_MS go.
export const addSample = (samples: readonly Sample[], pct: number, at: number): Sample[] => {
  const last = samples.at(-1)
  if (last && last.pct === pct) return [...samples]
  const kept = last && pct < last.pct ? [] : samples.filter(s => at - s.at <= 2 * RECENT_MS)
  return [...kept, { at, pct }]
}

export type Forecast = { atReset: number; fullAt?: number }

// Where the window ends up at this pace. The pace is the last RECENT_MS of samples when they span at least 5 minutes
// and moved at least 1 point, otherwise the window's average so far (not before 5% of it has passed). Null when there
// is not enough to go on, or the window is already full.
export const forecast = (
  pct: number | undefined,
  resetsAt: number | undefined,
  length: number,
  now: number,
  samples: readonly Sample[] = [],
): Forecast | null => {
  if (pct === undefined || resetsAt === undefined || resetsAt <= now || pct >= 100) return null
  const start = resetsAt - length
  const first = samples.find(s => s.at >= start && now - s.at <= RECENT_MS)
  const elapsed = now - start
  const rate =
    first && now - first.at >= MIN_SPAN_MS && pct - first.pct >= 1
      ? (pct - first.pct) / (now - first.at)
      : elapsed >= length * 0.05 && pct >= 1
        ? pct / elapsed
        : null
  if (rate === null) return null
  const atReset = pct + rate * (resetsAt - now)
  return atReset > 100 ? { atReset, fullAt: now + (100 - pct) / rate } : { atReset }
}

files.hooks/jet.ts:
// A fighter jet that shows the model's effort. Side view of a small 3D model: the wings,
// tail and canopy are rolled about the jet's long axis and projected each frame, so banks and rolls show the wings
// tilting. Pure SMIL, precomputed here: the desktop Svg element runs it without scripts.

import { SCHEME } from './svg'

export type JetLevel = 'low' | 'medium' | 'high' | 'xhigh' | 'max'

type Pace = { period: number; wind: number; flame: number; color: string; lines: number; shock: boolean }

// Lower effort answers faster: low flies fastest (short cycle, fast wind, full afterburner with shock diamonds), max
// cruises slowest (long cycle, slow wind, a small blue flame) since it thinks longest before answering.
export const PACE: Record<JetLevel, Pace> = {
  low: { period: 3.6, wind: 0.35, flame: 12, color: '#7F77DD', lines: 8, shock: true },
  medium: { period: 4.8, wind: 0.5, flame: 10, color: '#E24B4A', lines: 6, shock: false },
  high: { period: 6, wind: 0.7, flame: 8, color: '#EF9F27', lines: 5, shock: false },
  xhigh: { period: 7.2, wind: 0.95, flame: 6, color: '#F2C14E', lines: 4, shock: false },
  max: { period: 8.4, wind: 1.3, flame: 4, color: '#85B7EB', lines: 3, shock: false },
}

const LEVELS: readonly JetLevel[] = ['low', 'medium', 'high', 'xhigh', 'max']

// The effort turn.step reports: a level, or an integer thinking budget, flown as max (the slowest). A model without
// effort reports none: no jet.
export const jetLevel = (effort: unknown): JetLevel | null => {
  if (typeof effort === 'number') return 'max'
  return LEVELS.find(l => l === effort) ?? null
}

type P3 = readonly [number, number, number]
type Frame = { phi: number; dx: number; dy: number; pitch: number }

const FRAMES = 96
const BANK = 24
const ELEV = (14 * Math.PI) / 180 // the camera looks down a little, so level flight shows the near wing's top
const WIND = '#888780'
const GREY = '#9AA5B4'
const CAM = { y: -Math.sin(ELEV), z: Math.cos(ELEV) }
const LIGHT = (() => {
  const m = Math.hypot(0.75, 0.66)
  return { y: -0.75 / m, z: 0.66 / m }
})()

// Body frame: x forward, y down, z toward the viewer.
const FUSELAGE =
  'M15,0.4 C12,-0.6 9,-1.6 6,-2.0 L-2,-2.3 C-6,-2.4 -9,-2.2 -12,-1.9 L-13.2,-1.6 L-13.2,1.6 L-10,2.2 C-4,2.6 2,2.6 6,2.2 C9,1.9 12,1.2 15,0.4 Z'
const WING: P3[] = [[7.5, 0.6, 1.4], [2, 0.6, 2.6], [-5.5, 0.6, 8.6], [-8.6, 0.6, 8.6], [-9, 0.6, 2.0]]
const STAB: P3[] = [[-10, 0.4, 1.6], [-12.4, 0.4, 5.6], [-14.2, 0.4, 5.6], [-13.6, 0.4, 1.5]]
const FIN: P3[] = [[-6, -2.2, 0], [-10.8, -8.3, 0], [-12.8, -8.3, 0], [-12.6, -1.9, 0]]
const FLASH: P3[] = [[-9.78, -7, 0], [-10.8, -8.3, 0], [-12.8, -8.3, 0], [-12.76, -7, 0]]
const MISSILE: P3[] = [[-3.6, 0.6, 9.0], [-9.6, 0.6, 9.0]]
const UP: P3 = [0, -1, 0]
const SIDE: P3 = [0, 0, 1]

const mirror = (ps: P3[]): P3[] => ps.map(([x, y, z]) => [x, y, -z] as const)
const n2 = (n: number): string => String(Number(n.toFixed(2)))

const roll = (y: number, z: number, phi: number) => {
  const c = Math.cos(phi)
  const s = Math.sin(phi)
  return { y: y * c - z * s, z: y * s + z * c }
}

const project = ([x, y, z]: P3, phi: number) => {
  const r = roll(y, z, phi)
  return { x, y: r.y * Math.cos(ELEV) + r.z * Math.sin(ELEV), depth: r.z * Math.cos(ELEV) - r.y * Math.sin(ELEV) }
}

const shade = (hex: string, b: number): string => {
  const n = parseInt(hex.slice(1), 16)
  return `#${[(n >> 16) & 255, (n >> 8) & 255, n & 255]
    .map(v => Math.min(255, Math.round(v * b)).toString(16).padStart(2, '0'))
    .join('')}`
}

const ease = (t: number): number => (1 - Math.cos(Math.PI * t)) / 2

// One cycle: bank right, level, bank left, level, then a full roll while climbing a little (a corkscrew).
const KEYS: ReadonlyArray<readonly [number, number]> = [
  [0, 0], [0.12, BANK], [0.24, BANK], [0.36, 0], [0.48, -BANK], [0.6, -BANK], [0.7, 0], [0.72, 0], [0.9, 360], [1, 360],
]

const rollAt = (u: number): number => {
  for (let i = 0; i < KEYS.length - 1; i++) {
    const [a, from] = KEYS[i]
    const [b, to] = KEYS[i + 1]
    if (u <= b) return from + (to - from) * ease((u - a) / (b - a))
  }
  return 0
}

const frames = (): Frame[] =>
  Array.from({ length: FRAMES + 1 }, (_, i) => {
    const u = i / FRAMES
    let dy = -2.5 * Math.sin(4 * Math.PI * u)
    let dx = 0
    let pitch = -3 * Math.cos(4 * Math.PI * u)
    if (u > 0.72 && u < 0.9) {
      const g = (u - 0.72) / 0.18
      dy += -6 * Math.sin(Math.PI * g)
      dx += 3 * Math.sin(2 * Math.PI * g)
      pitch += -9 * Math.sin(2 * Math.PI * g)
    }
    return { phi: (rollAt(u) * Math.PI) / 180, dx, dy, pitch }
  })

const animate = (attr: string, values: string[], period: number, extra = ''): string =>
  `<animate attributeName="${attr}" values="${values.join(';')}" dur="${period}s" repeatCount="indefinite"${extra}/>`

const DISCRETE = ' calcMode="discrete"'

// A flat part drawn twice: behind the fuselage always, and in front of it (a <use>) while it faces the viewer.
const part = (id: string, pts: P3[], normal: P3 | null, base: string, fs: Frame[], period: number, stroke?: number) => {
  const shots = fs.map(f => {
    const q = pts.map(p => project(p, f.phi))
    const d = stroke
      ? `M${n2(q[0].x)},${n2(q[0].y)} L${n2(q[1].x)},${n2(q[1].y)}`
      : `M${q.map(p => `${n2(p.x)},${n2(p.y)}`).join(' L')} Z`
    const depth = q.reduce((a, p) => a + p.depth, 0) / q.length
    let color = base
    if (normal) {
      let n = roll(normal[1], normal[2], f.phi)
      if (n.y * CAM.y + n.z * CAM.z < 0) n = { y: -n.y, z: -n.z }
      color = shade(base, 0.55 + 0.6 * Math.max(0, n.y * LIGHT.y + n.z * LIGHT.z))
    }
    return { d, depth, color }
  })
  const paint = stroke ? 'stroke' : 'fill'
  const extra = stroke ? ` fill="none" stroke-width="${stroke}" stroke-linecap="round"` : ''
  return {
    back:
      `<path id="${id}" d="${shots[0].d}" ${paint}="${shots[0].color}"${extra}>` +
      animate('d', shots.map(s => s.d), period) +
      (normal ? animate(paint, shots.map(s => s.color), period) : '') +
      '</path>',
    front: `<use href="#${id}" opacity="0">${animate('opacity', shots.map(s => (s.depth > 0 ? '1' : '0')), period, DISCRETE)}</use>`,
  }
}

const flame = (pace: Pace): string => {
  const x = -15.4
  const shape = (len: number, h: number) =>
    `M${x},${n2(-h + 0.05)} Q${n2(x - len * 0.45)},${n2(-h)} ${n2(x - len)},0.05 Q${n2(x - len * 0.45)},${n2(h + 0.1)} ${x},${n2(h + 0.05)} Z`
  const layer = (len: number, h: number, fill: string, opacity: number) => {
    const a = shape(len, h)
    const b = shape(len * 0.78, h)
    return `<path d="${a}" fill="${fill}" opacity="${opacity}"><animate attributeName="d" values="${a};${b};${a}" dur="0.16s" repeatCount="indefinite"/></path>`
  }
  let s = layer(pace.flame * 1.35, 1.25, pace.color, 0.3) + layer(pace.flame, 0.95, pace.color, 0.9) + layer(pace.flame * 0.45, 0.55, '#FFF4D6', 0.95)
  // Shock diamonds in the plume at max.
  if (pace.shock) {
    for (const at of [0.35, 0.62]) {
      const cx = x - pace.flame * at
      s += `<path d="M${n2(cx + 0.5)},0.05 L${n2(cx)},-0.4 L${n2(cx - 0.5)},0.05 L${n2(cx)},0.5 Z" fill="#FFFFFF"><animate attributeName="opacity" values="0.9;0.35;0.9" dur="0.2s" repeatCount="indefinite"/></path>`
    }
  }
  return s
}

const jet = (pace: Pace, k: string): { defs: string; body: string } => {
  const T = pace.period
  const fs = frames()
  const wingFar = part(`${k}wf`, mirror(WING), UP, GREY, fs, T)
  const stabFar = part(`${k}sf`, mirror(STAB), UP, GREY, fs, T)
  const missileFar = part(`${k}mf`, mirror(MISSILE), null, '#E6EAF0', fs, T, 0.85)
  const wingNear = part(`${k}wn`, WING, UP, GREY, fs, T)
  const stabNear = part(`${k}sn`, STAB, UP, GREY, fs, T)
  const missileNear = part(`${k}mn`, MISSILE, null, '#E6EAF0', fs, T, 0.85)
  const fin = part(`${k}fn`, FIN, SIDE, '#97A2B1', fs, T)
  const flash = part(`${k}fl`, FLASH, SIDE, pace.color, fs, T)
  // The canopy is a dome on the spine: moved to its rolled place and squashed (flipped under) by cos(roll).
  const base = fs.map(f => project([3.2, -2.0, 0], f.phi))
  const top = fs.map(f => project([3.2, -2.3, 0], f.phi))
  const dome =
    `<g id="${k}cd"><animateTransform attributeName="transform" type="translate" values="${base.map(q => `${n2(q.x)} ${n2(q.y)}`).join(';')}" dur="${T}s" repeatCount="indefinite"/>` +
    `<g><animateTransform attributeName="transform" type="scale" values="${fs.map(f => `1 ${n2(Math.cos(f.phi))}`).join(';')}" dur="${T}s" repeatCount="indefinite"/>` +
    `<path d="M4.4,0 C3.6,-1.3 2.2,-2.1 0.4,-2.1 C-1.8,-2.1 -3.4,-1.1 -4.6,0 Z" fill="url(#${k}gg)"/>` +
    '<path d="M2.6,-1.55 C1.6,-1.85 0,-1.9 -1.4,-1.6" fill="none" stroke="#FFFFFF" stroke-width="0.35" stroke-linecap="round" opacity="0.75"/>' +
    '<path d="M1.6,-1.95 L2.1,-0.2" stroke="#1B2B3D" stroke-width="0.16" opacity="0.7"/></g></g>'
  const domeFront = `<use href="#${k}cd" opacity="0">${animate('opacity', base.map(q => (q.depth > -0.2 ? '1' : '0')), T, DISCRETE)}</use>`
  // Seen from above (rolled toward the viewer) the canopy reads as an oval on the fuselage.
  const oval =
    `<ellipse cx="3.2" cy="${n2(top[0].y)}" rx="4.1" ry="1.25" fill="url(#${k}gg)" opacity="0">` +
    animate('cy', top.map(q => n2(q.y)), T) +
    animate('opacity', fs.map(f => n2(Math.max(0, -Math.sin(f.phi)) ** 1.5)), T) +
    '</ellipse>'
  const fuselage =
    `<path d="${FUSELAGE}" fill="url(#${k}fg)"/>` +
    `<g clip-path="url(#${k}cp)"><rect x="11.4" y="-4" width="6" height="8" fill="#5B6573"/>` +
    '<path d="M-4,-1.9 C0,-1.3 6,-1.1 11,-1.0" fill="none" stroke="#FFFFFF" stroke-width="0.4" opacity="0.35"/></g>' +
    `<path d="${FUSELAGE}" fill="none" stroke="#3E4652" stroke-width="0.3" stroke-opacity="0.6"/>` +
    '<line x1="15" y1="0.4" x2="17.2" y2="0.4" stroke="#5B6573" stroke-width="0.3"/>' +
    '<path d="M-13.2,-1.6 L-15.4,-1.25 L-15.4,1.35 L-13.2,1.6 Z" fill="#454C57"/>' +
    '<line x1="-14.1" y1="-1.42" x2="-14.1" y2="1.48" stroke="#6B7480" stroke-width="0.25"/>' +
    '<line x1="-13.2" y1="-1.6" x2="-13.2" y2="1.6" stroke="#2F343C" stroke-width="0.35"/>'
  const defs =
    `<linearGradient id="${k}fg" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#DCE2EA"/><stop offset="0.3" stop-color="#B3BDCA"/><stop offset="0.7" stop-color="#848FA0"/><stop offset="1" stop-color="#5E6878"/></linearGradient>` +
    `<linearGradient id="${k}gg" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#0E2A47"/><stop offset="0.55" stop-color="#2C6E9E"/><stop offset="1" stop-color="#6FB3DB"/></linearGradient>` +
    `<clipPath id="${k}cp"><path d="${FUSELAGE}"/></clipPath>`
  const back = [wingFar, missileFar, stabFar, fin, flash, wingNear, missileNear, stabNear].map(p => p.back).join('')
  const front = [fin, flash, stabFar, wingFar, missileFar, stabNear, wingNear, missileNear].map(p => p.front).join('')
  const body =
    `<g><animateTransform attributeName="transform" type="translate" values="${fs.map(f => `${n2(f.dx)},${n2(f.dy)}`).join(';')}" dur="${T}s" repeatCount="indefinite"/>` +
    `<g><animateTransform attributeName="transform" type="rotate" values="${fs.map(f => n2(f.pitch)).join(';')}" dur="${T}s" repeatCount="indefinite"/>` +
    `${flame(pace)}${back}${dome}${fuselage}${front}${domeFront}${oval}</g></g>`
  return { defs, body }
}

// Speed lines streaming past: faster wind, more lines at higher effort. The wind moves at the same speed relative to
// the jet's size on every strip (pace.wind is the time to cross WIND_REF pixels at scale 1.25), so neither the band
// nor the larger pane looks slower than the other.
const WIND_REF = 340
const WIND_SCALE = 1.25
const wind = (pace: Pace, width: number, height: number, scale: number): string => {
  const dur = Number(Math.max(0.15, (pace.wind * (width + 40) * WIND_SCALE) / (WIND_REF * scale)).toFixed(2))
  let s = ''
  for (let i = 0; i < pace.lines; i++) {
    const y = 6 + ((i * 37) % Math.max(1, height - 10))
    const len = 10 + ((i * 7) % 14)
    const delay = -((i * dur) / pace.lines)
    s +=
      `<line x1="0" y1="${y}" x2="${len}" y2="${y}" stroke="${WIND}" stroke-width="1" stroke-linecap="round" opacity="0.45">` +
      `<animateTransform attributeName="transform" type="translate" values="${width + 10},0;-30,0" dur="${dur}s" begin="${delay.toFixed(2)}s" repeatCount="indefinite"/></line>`
  }
  return s
}

const cache = new Map<string, string>()

const escape = (s: string): string => s.replace(/&/g, '&amp;').replace(/</g, '&lt;')

// The whole strip: wind and the jet centered. Memoized: the frames are the same on every draw.
export const jetStrip = (level: JetLevel, width: number, height: number, scale: number, title: string, id = 'jet'): string => {
  const key = `${level}|${width}|${height}|${scale}|${title}|${id}`
  const hit = cache.get(key)
  if (hit !== undefined) return hit
  const pace = PACE[level]
  const { defs, body } = jet(pace, id)
  const svg =
    `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">${SCHEME}` +
    `<title>${escape(title)}</title><defs>${defs}</defs>${wind(pace, width, height, scale)}` +
    `<g transform="translate(${n2(width / 2 + 6)},${n2(height / 2 + 2)}) scale(${scale})">${body}</g></svg>`
  if (cache.size > 24) cache.clear()
  cache.set(key, svg)
  return svg
}

